verify:
choices = {o: choices[n] for o, n in {'A': 'A', 'B': 'B', 'C': 'C', 'D': 'D'}.items()}; answer = {'A': 'A', 'B': 'B', 'C': 'C', 'D': 'D'}[answer]  # shuffled: original letters
def possible(p, q):
    return p > 0 or q > 0
pts = {'A': (3, -5), 'B': (1, 4), 'C': (-2, -1), 'D': (-1, 7)}
for kk, (p, q) in pts.items():
    assert choices[kk] == '\\((%d, %d)\\)' % (p, q)
assert [k for k in pts if not possible(*pts[k])] == [answer]
assert -3*3 + 4 == -5 and -1 + 5 == 4 and 2 + 5 == 7
assert all(Rational(-2)*a + b > 0 for a, b in [(-Rational(1, 100), Rational(1, 100)), (-5, 1)])
